<title>Rooftop Courier · A little city, a long way up</title>
<style>
:root{--ink:#233b50;--paper:#f4ead8;--blue:#244fd3;--orange:#bd4b2b;--line:#d3c4aa}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Trebuchet MS",Verdana,sans-serif}
button,select{font:inherit}button,a,select{-webkit-tap-highlight-color:transparent}a{color:inherit}button{cursor:pointer}
button:focus-visible,a:focus-visible,select:focus-visible,[role=button]:focus-visible{outline:3px solid var(--blue);outline-offset:4px}
.mast{max-width:1240px;margin:auto;padding:24px 32px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:11px;letter-spacing:2px;text-transform:uppercase}
.mast a{text-decoration:none}.edition{color:var(--orange)}main{max-width:1240px;margin:auto;padding:32px}
.hero{display:grid;grid-template-columns:1.1fr 1fr;gap:42px;align-items:center;margin-bottom:36px}
.kicker{font:12px "Courier New",monospace;letter-spacing:3px;text-transform:uppercase;color:var(--orange)}
