h1 em{font-style:italic;color:var(--blue)}.intro{max-width:420px;line-height:1.7;font-size:16px}.art{margin:0;position:relative;transform:rotate(2deg);background:#e6d4b5;padding:9px;box-shadow:5px 10px 0 #233b5012}
.art img{width:100%;display:block;aspect-ratio:3/2;object-fit:cover}.art figcaption{font:11px "Courier New",monospace;padding:10px 5px 3px;letter-spacing:1px}
.play{border:1px solid var(--line);display:grid;grid-template-columns:minmax(0,1fr) 290px;background:#fffaf0;box-shadow:0 16px 35px #80623c0d}
.city{position:relative;min-width:0;background:radial-gradient(ellipse at 50% 65%,#e6ce9c60,transparent 65%);display:flex;flex-direction:column}
.cityhead{padding:22px 26px 0;display:flex;justify-content:space-between;gap:10px;font:12px "Courier New",monospace;text-transform:uppercase;letter-spacing:1px}
#board{width:100%;display:block;min-height:250px;touch-action:manipulation}#board text{pointer-events:none;font-family:"Trebuchet MS",sans-serif}
.tile{cursor:pointer;outline:none}.tile>*{pointer-events:none}.tile .roof{pointer-events:all}.tile:hover .roof,.tile:focus .roof{stroke:#244fd3;stroke-width:4}.tile .roof{transition:fill .15s}
.legend{padding:0 24px 22px;display:flex;gap:20px;flex-wrap:wrap;font-size:12px;color:#53616a}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;background:var(--blue);margin-right:5px}.dot.gold{background:#d79a21}
aside{border-left:1px solid var(--line);padding:24px}.dispatch{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;font:11px "Courier New",monospace;letter-spacing:2px}
.stamp{border:1px solid var(--orange);border-radius:50%;width:43px;height:43px;display:grid;place-items:center;color:var(--orange);transform:rotate(-12deg);font-size:20px}
