.stats{display:flex;gap:28px;margin:20px 0}.stat b{display:block;font:38px Georgia,serif;color:var(--blue)}.stat span{font:10px "Courier New",monospace;text-transform:uppercase;letter-spacing:1px}
.tools{display:grid;grid-template-columns:1fr 1fr;gap:5px;padding:5px;background:#e9dfcd;border-radius:6px}
