#message{line-height:1.6;font-size:14px;min-height:76px;padding:14px 0;color:#4c5c65}#message.success{color:#286244;font-weight:bold}
.secondary{display:flex;gap:8px;flex-wrap:wrap}.secondary button,#next{min-height:42px;padding:9px 13px;color:var(--ink);border:1px solid var(--line);background:transparent;border-radius:3px}.secondary button:disabled{opacity:.4;cursor:default}
#next{background:var(--orange);color:white;border-color:var(--orange);width:100%;margin-top:15px}#next[hidden]{display:none}
.routes{margin-top:22px;border-top:1px solid var(--line);padding-top:18px}label{display:block;font:11px "Courier New",monospace;letter-spacing:1px;text-transform:uppercase;margin-bottom:9px}select{width:100%;padding:10px 6px;background:#fffaf0;color:var(--ink);border:1px solid var(--line)}
.rules{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;padding:32px 0;border-bottom:1px solid var(--line)}.rule{line-height:1.6;font-size:14px}.rule b{display:block;font-family:Georgia,serif;font-size:21px;font-weight:normal;margin-bottom:8px}.rule small{color:var(--orange);font:11px "Courier New",monospace;margin-right:8px}
footer{line-height:1.8;color:#59656a;font-size:12px;padding:25px 0;max-width:800px}kbd{border:1px solid var(--line);padding:1px 4px;border-radius:3px;font-size:11px}
@media(max-width:850px){.hero{gap:25px}.play{grid-template-columns:1fr 260px}aside{padding:20px}h1{letter-spacing:-3px}.mast,main{padding:22px}}
@media(max-width:650px){.mast{font-size:9px;letter-spacing:1px;padding:18px}.hero{grid-template-columns:1fr;gap:20px;margin-bottom:27px}.hero .art{max-width:100%;transform:rotate(1deg)}main{padding:22px 16px}.intro{margin:0;max-width:none;font-size:14px}.hero h1{font-size:66px;line-height:.92;margin:15px 0}.hero .art img{aspect-ratio:2.3;object-position:50% 55%}.play{grid-template-columns:1fr}.cityhead{padding:20px 16px 0;font-size:10px}.legend{padding:0 16px 20px;font-size:11px;gap:12px}aside{border-left:0;border-top:1px solid var(--line);padding:20px}h2{margin-top:18px}#brief{min-height:0}.stats{margin:16px 0}#message{min-height:60px}.rules{grid-template-columns:1fr;gap:18px;padding:25px 0}.rule b{margin-bottom:4px}.art figcaption{font-size:9px}.dispatch{padding-bottom:12px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
